output_text:
[
  {
    "id": "must_take_cart",
    "text": "A shopper is obliged to take the available cart before completing the trip.",
    "abstraction": {
      "state_properties": {
        "at_cart_start": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "cart_acquired": {
          "pre": {
            "and": [
              "at_cart_start",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "cart_acquired"
    }
  },
  {
    "id": "no_hand_shopping",
    "text": "Items should not be carried by hand; a shopper may pick up shelf items only while using a cart.",
    "abstraction": {
      "state_properties": {
        "no_cart": {
          "not": "hasCart"
        },
        "carrying_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          {
            "and": [
              "PICKUP_ITEM",
              "no_cart"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "return_cart_to_front_bay",
    "text": "After taking a cart, the shopper is obliged to return it to the front cart-return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)",
        "cart_returned_front": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "cart_acquired": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "front_cart_return": {
          "pre": {
            "and": [
              "front_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_acquired",
      "discharge": "front_cart_return"
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "A shopper is forbidden to put the cart down anywhere except the designated return bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "LEAVE_CART",
          {
            "not": "front_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper may not exit the supermarket while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_possession": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "cart_in_possession"
        ]
      }
    }
  },
  {
    "id": "no_unattended_cart_off_station",
    "text": "An unattended cart may be left only at a recognized cart station, namely its starting station at (1,5) or the return bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_at_start_station": "cartAt(1,5)",
        "cart_at_return_station": "cartAt(0,1)",
        "cart_at_approved_station": {
          "or": [
            "cart_at_start_station",
            "cart_at_return_station"
          ]
        },
        "cart_unattended": {
          "not": "hasCart"
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_unattended",
          {
            "not": "cart_at_approved_station"
          }
        ]
      }
    }
  },
  {
    "id": "no_more_interactions_after_return",
    "text": "Once the cart has been returned to the front bay, the shopper should not resume shopping or interact with objects again before leaving.",
    "abstraction": {
      "state_properties": {
        "cart_returned_front": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cart_returned_front",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "shopping_pickup_requires_later_cart_return",
    "text": "After any shelf item is picked up, the shopper is obliged eventually to return the cart at the front bay before the trip ends.",
    "abstraction": {
      "state_properties": {
        "front_return_bay": "at(0,1)"
      },
      "events": {
        "item_taken": {
          "pre": "PICKUP_ITEM",
          "post": null
        },
        "front_cart_return": {
          "pre": {
            "and": [
              "front_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_taken",
      "discharge": "front_cart_return"
    }
  }
]
